local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({0,4}),"int32"),{2,1})
local before=x:tolist()
local out=np.zeros({4,0},"int32")
local y=r:permuted(x,-1,out)
deep(y.dtype,"int32","0/(0, 4)/int32/transpose/-1/out_new dtype")
deep(y:tolist(),{{},{},{},{}},"0/(0, 4)/int32/transpose/-1/out_new values")
deep(x:tolist(),{{},{},{},{}},"0/(0, 4)/int32/transpose/-1/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"a30febcfd9c2825f","0/(0, 4)/int32/transpose/-1/out_new pcg")
cases=cases+1; end
