local x=np.transpose(np.astype(np.arange(0,"int64"):reshape({0,4}),"uint8"),{2,1})
local before=x:tolist()
local out=np.zeros({4,0},"uint8")
local y=r:permuted(x,1,out)
deep(y.dtype,"uint8","0/(0, 4)/uint8/transpose/0/out_new dtype")
deep(y:tolist(),{{},{},{},{}},"0/(0, 4)/uint8/transpose/0/out_new values")
deep(x:tolist(),{{},{},{},{}},"0/(0, 4)/uint8/transpose/0/out_new source")
assert(rawequal(y,out),"out must return identical ndarray")
deep(r:raw_hex(),"a30febcfd9c2825f","0/(0, 4)/uint8/transpose/0/out_new pcg")
cases=cases+1; end
